691			\begin{equation}\label{eq:bound-on-r}
692				r
693				=
694				\sum_a r_a
695				=
696				\sum_a \Tr(R_a)
697				=
698				\Tr(R)
699				\leq
700				(1+2\sqrt{\zeta})d.
701			\end{equation}
702			Let $\ket{v_{a,1}},\ldots,\ket{v_{a,r_a}}$ be an orthonormal basis for the range of $R_a$, so
703			\[
704				R_a = \sum_{i=1}^{r_a} \ket{v_{a,i}}\bra{v_{a,i}}.
705			\]
706			Define the overlaps
707			\[
708				o_{a,i} = \bra{\psi} (\ket{v_{a,i}}\bra{v_{a,i}} \ot I)\ket{\psi}.
709			\]
710			Their total satisfies
711			\begin{equation}\label{eq:total-overlap}
712				\sum_a \sum_{i=1}^{r_a} o_{a,i}
713				=
714				\bra{\psi} R \ot I \ket{\psi}
715				\leq
716				1+2\sqrt{\zeta}.
717			\end{equation}
718			Let $\mathsf{Large}$ be the set of the $d$ largest overlaps $o_{a,i}$, breaking ties arbitrarily, and let $\mathsf{Small}$ be the complement. Then
719			\begin{equation}\label{eq:size-of-small-is-small}
720				|\mathsf{Small}|
721				=
722				r-d
723				\leq
724				2\sqrt{\zeta}\,d
725				\leq
726				2\sqrt{\zeta}\,r,
727			\end{equation}
728			by \ref{eq:bound-on-r}. Averaging the overlaps over the $r$ indices gives
729			\begin{equation}\label{eq:small-overlaps}
730				\sum_{(a,i)\in \mathsf{Small}} o_{a,i}
731				\leq
732				\frac{|\mathsf{Small}|}{r}\sum_{a,i} o_{a,i}
733				\leq
734				4\sqrt{\zeta},
735			\end{equation}
736			using \ref{eq:size-of-small-is-small}, \ref{eq:total-overlap}, and \ref{eq:assumption-on-zeta}.
737	
738			For each $a$, let $\mathsf{Large}_a=\{i : (a,i)\in \mathsf{Large}\}$ and define
739			\[
740				Q_a = \sum_{i \in \mathsf{Large}_a} \ket{v_{a,i}}\bra{v_{a,i}}.
741			\]
742			Then $\sum_a \mathrm{rank}(Q_a)=|\mathsf{Large}| \leq d$, and $Q_a \leq R_a$ for every $a$, so
743			\[
744				Q = \sum_a Q_a \leq \sum_a R_a = R \leq (1+2\sqrt{\zeta})I.
745			\]
746			Also,
747			\[
748				R_a-Q_a = \sum_{i \in \mathsf{Small}_a} \ket{v_{a,i}}\bra{v_{a,i}}
749			\]
750			is a projector, hence
751			\[
752				\sum_a \Vert (R_a-Q_a)\ot I \ket{\psi}\Vert^2
753				=
754				\sum_{(a,i)\in\mathsf{Small}} o_{a,i}
755				\leq
756				4\sqrt{\zeta}
757			\]
758			by \ref{eq:small-overlaps}. Therefore $R_a \ot I \approx_{4\sqrt{\zeta}} Q_a \ot I$. Combining this with \ref{lem:projective-non-measurement} and the triangle inequality for $\approx_\delta$ gives
759			\[
760				A_a \ot I \approx_{12\sqrt{\zeta}} Q_a \ot I.
