767			\lean{MIPStarRE.LDT.MakingMeasurementsProjective.qCompleteness}
768			\leanok
769			\begin{equation*}
770				\bra{\psi} Q \ot I \ket{\psi}
771				\geq
772				1 - 11 \zeta^{1/4}.
773			\end{equation*}
774		\end{lemma}
775		\begin{proof}
776			\leanok
777			\uses{lem:projective-low-rank-sum}
778			Since each $Q_a$ is projective,
779			\begin{equation}\label{eq:Q-for-an-A}
780				\bra{\psi} Q \ot I \ket{\psi}
781				=
782				\sum_a \bra{\psi} (Q_a)^2 \ot I \ket{\psi}
783				\approx_{5\zeta^{1/4}}
784				\sum_a \bra{\psi} (Q_a \cdot A_a)\ot I \ket{\psi}.
785			\end{equation}
786			By Cauchy--Schwarz,
787			\[
788				\sum_a \bra{\psi} (Q_a)^2 \ot I \ket{\psi} \leq 1+2\sqrt{\zeta}
789				\quad\text{and}\quad
790				\sum_a \bra{\psi} (Q_a-A_a)^2 \ot I \ket{\psi} \leq 12\sqrt{\zeta}
791			\]
792			from \ref{lem:projective-low-rank-sum}.
793			A second Cauchy--Schwarz estimate yields
794			\begin{equation}\label{eq:another-Q-for-A}
795				\sum_a \bra{\psi} (Q_a \cdot A_a)\ot I \ket{\psi}
796				\approx_{4\zeta^{1/4}}
797				\sum_a \bra{\psi} (A_a)^2 \ot I \ket{\psi}.
798			\end{equation}
799			Combining \ref{eq:Q-for-an-A} and \ref{eq:another-Q-for-A} with \ref{eq:A-looks-projective} gives
800			\[
801				\bra{\psi} Q \ot I \ket{\psi}
802				\geq
803				\sum_a \bra{\psi} A_a \ot I \ket{\psi} - 2\zeta - 9\zeta^{1/4}
804				=
805				1 - 11\zeta^{1/4},
806			\]
807			since $\zeta \leq \zeta^{1/4}$ under \ref{eq:assumption-on-zeta}.
808		\end{proof}
