167	\begin{definition}[Consistent measurements]\label{def:consistent-measurement}
168		\lean{MIPStarRE.QPBT.Measurement.IsConsistentOn}
169		\leanok
170		\uses{def:povm-conventions}
171		Let $\mathcal A$ be a finite set, let $\ket{\psi} \in \mathcal H \ot \mathcal H$ be a state, and let $\{M_a\}_{a \in \mathcal A}$ be a projective measurement on $\mathcal H$. We say that \emph{$\{M_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$} if and only if
172		\[
173			\forall a \in \mathcal A\,, \qquad M_a \ot \Id_B\, \ket{\psi} = \Id_A \ot M_a\, \ket{\psi}\,.
174		\]
175		When the state $\ket{\psi}$ is clear from context we simply say that $\{M_a\}_{a \in \mathcal A}$ is consistent.
176	\end{definition}
177	
178	The terminology arises from the fact that when the measurement $\{M_a\}$ is performed on both registers of $\ket{\psi}$, the probability of obtaining twice the same outcome is
179	\[
180		\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot (M_a)^2 \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot M_a \ket{\psi} = 1\,,
181	\]
182	where the first equality is by the definition of consistency, the second uses that $\{M_a\}$ is projective, and the last uses $\sum_a M_a = \Id$.
